using System.Text;

// CA1305: the emitters only interpolate integers and strings, and Generator.Render runs under the invariant culture.
#pragma warning disable CA1305

namespace Quire.ProtocolGen;

/// <summary>Emits the C++ half: enums, payload structs with validate/encode/decode, and the message-type switches.</summary>
internal static class CppEmitter
{
    private const string Header =
        "// <auto-generated>\n" +
        "// Generated by tools/Quire.ProtocolGen from src/Quire.Protocol/schema/quire.protocol.json. Do not edit.\n" +
        "// </auto-generated>\n";

    private const string Dir = "src/Quire.Protocol/generated/cpp/quire/protocol/";

    public static IEnumerable<(string Path, string Content)> Emit(Schema s)
    {
        yield return (Dir + "enums.h", Enums(s));
        yield return (Dir + "messages.h", MessagesHeader(s));
        yield return (Dir + "messages.cpp", MessagesSource(s));
    }

    private static string Enums(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("#pragma once\n\n#include <cstddef>\n#include <cstdint>\n\nnamespace quire::protocol {\n\n");
        b.Append($"inline constexpr std::uint32_t kSchemaVersion = {s.SchemaVersion};\n");
        b.Append($"inline constexpr std::size_t kMaxFrameBytes = {s.MaxFrameBytes};\n");
        b.Append($"inline constexpr std::uint32_t kMaxDeadlineMs = {s.MaxDeadlineMs};\n\n");

        foreach (var e in s.Enums)
        {
            var snake = Schema.Snake(e.Name);
            b.Append($"enum class {e.Name} : std::uint16_t {{\n");
            foreach (var v in e.Values) b.Append($"    {v.Name} = {v.Value},\n");
            b.Append("};\n\n");
            b.Append($"[[nodiscard]] constexpr bool is_defined_{snake}(std::uint16_t raw) noexcept {{\n    switch (raw) {{\n");
            foreach (var v in e.Values) b.Append($"        case {v.Value}:\n");
            b.Append("            return true;\n        default:\n            return false;\n    }\n}\n\n");
            if (e.Name == "Status")
            {
                b.Append("/// True for statuses whose response carries a reply payload; all others carry nil.\n");
                b.Append("[[nodiscard]] constexpr bool carries_payload(Status status) noexcept {\n    switch (status) {\n");
                foreach (var v in e.Values.Where(v => v.CarriesPayload)) b.Append($"        case Status::{v.Name}:\n");
                b.Append("            return true;\n        default:\n            return false;\n    }\n}\n\n");
            }
        }

        b.Append("/// Wire id of a request/reply pair. The reply carries the id of the request it answers.\nenum class MessageType : std::uint16_t {\n");
        foreach (var m in s.Messages) b.Append($"    {m.Name} = {m.Id},\n");
        b.Append("};\n\n");
        b.Append("[[nodiscard]] constexpr bool is_defined_message_type(std::uint16_t raw) noexcept {\n    switch (raw) {\n");
        foreach (var m in s.Messages) b.Append($"        case {m.Id}:\n");
        b.Append("            return true;\n        default:\n            return false;\n    }\n}\n\n");
        b.Append("enum class DocumentIdRule : std::uint8_t {\n    None,      // header documentId must be 0\n    Required,  // header documentId must be non-zero\n};\n\n");
        b.Append("[[nodiscard]] constexpr DocumentIdRule document_rule(MessageType type) noexcept {\n    switch (type) {\n");
        foreach (var m in s.Messages) b.Append($"        case MessageType::{m.Name}:\n            return DocumentIdRule::{m.DocumentId};\n");
        b.Append("    }\n    return DocumentIdRule::Required;\n}\n\n}  // namespace quire::protocol\n");
        return b.ToString();
    }

    private static string CppType(FieldType t, FieldDef f) => t switch
    {
        FieldType.U16 => "std::uint16_t",
        FieldType.U32 => "std::uint32_t",
        FieldType.U64 => "std::uint64_t",
        FieldType.I32 => "std::int32_t",
        FieldType.F32 => "float",
        FieldType.Bool => "bool",
        FieldType.Text => "std::string",
        FieldType.Enum => f.EnumName!,
        _ => throw new InvalidOperationException(t.ToString()),
    };

    private static string Member(FieldDef f) => Schema.Snake(f.Name);

    private static string MemberType(FieldDef f) => f.Type switch
    {
        FieldType.Array => $"std::vector<{CppType(f.Element!.Value, f)}>",
        FieldType.Text when f.Optional => "std::optional<std::string>",
        _ => CppType(f.Type, f),
    };

    private static string MessagesHeader(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("#pragma once\n\n#include <cstdint>\n#include <optional>\n#include <string>\n#include <variant>\n#include <vector>\n\n");
        b.Append("#include \"quire/protocol/enums.h\"\n#include \"quire/protocol/msgpack.h\"\n\nnamespace quire::protocol {\n");

        foreach (var m in s.Messages)
        {
            foreach (var st in new[] { m.Request, m.Reply })
            {
                b.Append($"\n/// {(st == m.Request ? "Request" : "Reply")} payload of {m.Name} (message type {m.Id}).\n");
                b.Append($"struct {st.TypeName} {{\n    static constexpr MessageType kMessageType = MessageType::{m.Name};\n");
                foreach (var f in st.Fields)
                {
                    if (f.Doc is not null) b.Append($"    /// {f.Doc}\n");
                    b.Append($"    {MemberType(f)} {Member(f)}{{}};\n");
                }

                b.Append("\n    /// Checks every schema limit.\n    [[nodiscard]] Status validate() const;\n");
                b.Append("    /// Validates, then writes the payload array. Writes nothing if validation fails.\n    [[nodiscard]] Status encode(Writer& writer) const;\n");
                b.Append($"    /// Reads and fully validates one payload. The value is default-constructed on failure.\n    [[nodiscard]] static Result<{st.TypeName}> decode(Reader& reader);\n\n");
                b.Append($"    bool operator==(const {st.TypeName}&) const = default;\n}};\n");
            }
        }

        b.Append("\nusing RequestPayload = std::variant<" + string.Join(", ", s.Messages.Select(m => m.Request.TypeName)) + ">;\n");
        b.Append("using ReplyPayload = std::variant<" + string.Join(", ", s.Messages.Select(m => m.Reply.TypeName)) + ">;\n\n");
        b.Append("/// Decode the payload of a request or reply of the given type. An unknown type is a ProtocolError.\n");
        b.Append("[[nodiscard]] Result<RequestPayload> decode_request_payload(MessageType type, Reader& reader);\n");
        b.Append("[[nodiscard]] Result<ReplyPayload> decode_reply_payload(MessageType type, Reader& reader);\n\n");
        b.Append("}  // namespace quire::protocol\n");
        return b.ToString();
    }

    private static string Lit(FieldType t, decimal v) => t switch
    {
        FieldType.U32 => Schema.Inv(v) + "u",
        FieldType.U64 => Schema.Inv(v) + "ull",
        FieldType.F32 => CSharpEmitter.FloatLit(v) + "f",
        _ => Schema.Inv(v),
    };

    private static string Bound(FieldType t, FieldDef f, bool upper)
    {
        var v = upper ? f.Max : f.Min ?? f.ExclusiveMin;
        if (v is not null) return Lit(t, v.Value);
        return t switch
        {
            FieldType.I32 => $"std::numeric_limits<std::int32_t>::{(upper ? "max" : "min")}()",
            FieldType.U16 => upper ? "65535" : "0",
            FieldType.U32 => upper ? "4294967295u" : "0u",
            FieldType.U64 => upper ? "18446744073709551615ull" : "0ull",
            _ => throw new InvalidOperationException(t.ToString()),
        };
    }

    // The failing condition in validate() for one value of scalar type t, or null if only the type constrains it.
    private static string? Condition(FieldType t, FieldDef f, string x)
    {
        switch (t)
        {
            case FieldType.Bool:
                return null;
            case FieldType.Enum:
                return $"!is_defined_{Schema.Snake(f.EnumName!)}(static_cast<std::uint16_t>({x}))";
            case FieldType.Text:
                return f.Optional
                    ? $"{x}.has_value() && (({x})->size() > {f.MaxBytes}u || !is_valid_text(*{x}))"
                    : $"{x}.size() > {f.MaxBytes}u || !is_valid_text({x})";
            case FieldType.F32:
                var parts = new List<string> { $"!std::isfinite({x})" };
                if (f.Min is not null) parts.Add($"{x} < {Lit(t, f.Min.Value)}");
                if (f.ExclusiveMin is not null) parts.Add($"{x} <= {Lit(t, f.ExclusiveMin.Value)}");
                parts.Add($"{x} > {Lit(t, f.Max!.Value)}");
                return string.Join(" || ", parts);
            default:
                var (lo, hi) = Schema.Range(t);
                var ints = new List<string>();
                if (f.Min is not null && f.Min > lo) ints.Add($"{x} < {Lit(t, f.Min.Value)}");
                if (f.Max is not null && f.Max < hi) ints.Add($"{x} > {Lit(t, f.Max.Value)}");
                return ints.Count == 0 ? null : string.Join(" || ", ints);
        }
    }

    private static string ReadCall(FieldType t, FieldDef f, string target) => t switch
    {
        FieldType.U16 => $"reader.read_u16({target}, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.U32 => $"reader.read_u32({target}, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.U64 => $"reader.read_u64({target}, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.I32 => $"reader.read_i32({target}, {Bound(t, f, false)}, {Bound(t, f, true)})",
        FieldType.F32 => $"reader.read_f32({target}, {Bound(t, f, false)}, {Bound(t, f, true)}, {(f.ExclusiveMin is not null ? "true" : "false")})",
        FieldType.Bool => $"reader.read_bool({target})",
        FieldType.Text when f.Optional => $"reader.read_optional_string({target}, {f.MaxBytes})",
        FieldType.Text => $"reader.read_string({target}, {f.MaxBytes})",
        FieldType.Enum => $"reader.read_enum({target}, is_defined_{Schema.Snake(f.EnumName!)})",
        _ => throw new InvalidOperationException(t.ToString()),
    };

    private static string WriteCall(FieldType t, FieldDef f, string x) => t switch
    {
        FieldType.U16 or FieldType.U32 or FieldType.U64 => $"writer.write_uint({x});",
        FieldType.I32 => $"writer.write_int({x});",
        FieldType.F32 => $"writer.write_f32({x});",
        FieldType.Bool => $"writer.write_bool({x});",
        FieldType.Text when f.Optional => $"if ({x}) {{ writer.write_string(*{x}); }} else {{ writer.write_nil(); }}",
        FieldType.Text => $"writer.write_string({x});",
        FieldType.Enum => $"writer.write_uint(static_cast<std::uint16_t>({x}));",
        _ => throw new InvalidOperationException(t.ToString()),
    };

    private static string MessagesSource(Schema s)
    {
        var b = new StringBuilder(Header);
        b.Append("#include \"quire/protocol/messages.h\"\n\n#include <cmath>\n#include <limits>\n#include <utility>\n\nnamespace quire::protocol {\n");

        foreach (var m in s.Messages)
        {
            foreach (var st in new[] { m.Request, m.Reply })
            {
                var t = st.TypeName;

                // validate
                b.Append($"\nStatus {t}::validate() const {{\n");
                foreach (var f in st.Fields)
                {
                    var x = Member(f);
                    if (f.Type == FieldType.Array)
                    {
                        b.Append($"    if ({x}.size() > {f.MaxCount}u) {{\n        return Status::InvalidArgument;\n    }}\n");
                        var cond = Condition(f.Element!.Value, f, "v");
                        if (cond is not null)
                            b.Append($"    for (const auto& v : {x}) {{\n        if ({cond}) {{\n            return Status::InvalidArgument;\n        }}\n    }}\n");
                    }
                    else if (Condition(f.Type, f, x) is { } cond)
                    {
                        b.Append($"    if ({cond}) {{\n        return Status::InvalidArgument;\n    }}\n");
                    }
                }

                foreach (var f in st.Fields.Where(f => f.SameLengthAs is not null))
                    b.Append($"    if ({Member(f)}.size() != {Schema.Snake(f.SameLengthAs!)}.size()) {{\n        return Status::InvalidArgument;\n    }}\n");
                b.Append("    return Status::Ok;\n}\n");

                // encode
                b.Append($"\nStatus {t}::encode(Writer& writer) const {{\n");
                b.Append("    if (const Status valid = validate(); valid != Status::Ok) {\n        return valid;\n    }\n");
                b.Append($"    writer.write_array_header({st.Fields.Count});\n");
                foreach (var f in st.Fields)
                {
                    var x = Member(f);
                    if (f.Type == FieldType.Array)
                        b.Append($"    writer.write_array_header({x}.size());\n    for (const auto& v : {x}) {{\n        {WriteCall(f.Element!.Value, f, "v")}\n    }}\n");
                    else
                        b.Append($"    {WriteCall(f.Type, f, x)}\n");
                }

                b.Append("    return writer.status();\n}\n");

                // decode
                b.Append($"\nResult<{t}> {t}::decode(Reader& reader) {{\n    {t} m;\n");
                b.Append($"    Status s = reader.expect_array({st.Fields.Count});\n");
                foreach (var f in st.Fields)
                {
                    var x = "m." + Member(f);
                    if (f.Type == FieldType.Array)
                    {
                        b.Append("    if (s == Status::Ok) {\n        std::size_t count = 0;\n");
                        b.Append($"        s = reader.read_array_header(count, {f.MaxCount});\n");
                        b.Append($"        if (s == Status::Ok) {{\n            {x}.reserve(count);\n");
                        b.Append("            for (std::size_t i = 0; i < count && s == Status::Ok; ++i) {\n");
                        b.Append($"                {CppType(f.Element!.Value, f)} v{{}};\n");
                        b.Append($"                s = {ReadCall(f.Element.Value, f, "v")};\n");
                        b.Append($"                if (s == Status::Ok) {{\n                    {x}.push_back(std::move(v));\n                }}\n            }}\n        }}\n    }}\n");
                    }
                    else
                    {
                        b.Append($"    if (s == Status::Ok) {{\n        s = {ReadCall(f.Type, f, x)};\n    }}\n");
                    }
                }

                b.Append("    if (s == Status::Ok) {\n        s = m.validate();\n        if (s != Status::Ok) {\n            reader.fail(s, \"message violates a schema limit\");\n        }\n    }\n");
                b.Append($"    if (s != Status::Ok) {{\n        return {{s, {t}{{}}, reader.detail()}};\n    }}\n");
                b.Append("    return {Status::Ok, std::move(m), \"\"};\n}\n");
            }
        }

        b.Append("\nnamespace {\n\ntemplate <class Variant, class T>\nResult<Variant> lift(Result<T>&& result) {\n    if (!result.ok()) {\n        return {result.status, Variant{}, result.detail};\n    }\n");
        b.Append("    return {Status::Ok, Variant{std::in_place_type<T>, std::move(result.value)}, \"\"};\n}\n\n}  // namespace\n");

        foreach (var (name, variant, pick) in new (string, string, Func<MessageDef, StructDef>)[]
        {
            ("decode_request_payload", "RequestPayload", m => m.Request),
            ("decode_reply_payload", "ReplyPayload", m => m.Reply),
        })
        {
            b.Append($"\nResult<{variant}> {name}(MessageType type, Reader& reader) {{\n    switch (type) {{\n");
            foreach (var m in s.Messages)
                b.Append($"        case MessageType::{m.Name}:\n            return lift<{variant}>({pick(m).TypeName}::decode(reader));\n");
            b.Append($"    }}\n    return {{Status::ProtocolError, {variant}{{}}, \"unknown message type\"}};\n}}\n");
        }

        b.Append("\n}  // namespace quire::protocol\n");
        return b.ToString();
    }
}
